#!/usr/bin/env python3
"""Install source-selection picons and matching tile styling; no playback changes."""
import argparse
import ast
import base64
from datetime import datetime
import hashlib
import os
from pathlib import Path
import re
import shutil
import stat
import sys
import tempfile
import xml.etree.ElementTree as ET

RUNTIME = "# EMBYFLOW_SOURCE_SETUP_PICONS_V1_20261031_BEGIN\n_EFSP_DIR = os.path.join(PLUGIN_PATH, 'assets', 'source_setup_v1')\n_EFSP_INIT = EmbyFlowLocalAddSourceScreenV18.__init__\n_EFSP_LAYOUT = EmbyFlowLocalAddSourceScreenV18.layout_ready\n_EFSP_LOCATIONS = EmbyFlowLocalAddSourceScreenV18.refresh_locations\n_EFSP_FOCUS = EmbyFlowLocalAddSourceScreenV18.apply_focus\n\n\ndef _efsp_load(screen, name, filename):\n    path = os.path.join(_EFSP_DIR, filename + '.png')\n    try:\n        screen[name].instance.setPixmapFromFile(path)\n        screen[name].instance.setScale(1)\n        screen[name].show()\n    except Exception:\n        pass\n\n\ndef _efsp_init(screen, *args, **kwargs):\n    _EFSP_INIT(screen, *args, **kwargs)\n    screen['source_card_fill'] = Label(' ')\n\n\ndef _efsp_storage_icons(screen):\n    for index in range(4):\n        if index >= len(screen.locations):\n            screen['storage_icon%d' % index].hide()\n            continue\n        item = screen.locations[index]\n        path = str(item.get('path') or '')\n        kind = str(item.get('icon') or '')\n        network = kind in ('nas.png', 'globe_v18.png') or path.startswith(('/media/net', '/media/autofs'))\n        icon = 'network' if network else 'usb' if path.startswith('/media/usb') else 'disk' if kind == 'drive.png' or path.startswith('/media/hdd') else 'folder_link'\n        _efsp_load(screen, 'storage_icon%d' % index, icon)\n\n\ndef _efsp_locations(screen):\n    result = _EFSP_LOCATIONS(screen)\n    _efsp_storage_icons(screen)\n    return result\n\n\ndef _efsp_layout(screen):\n    result = _EFSP_LAYOUT(screen)\n    for index, icon in enumerate(('disk_usb', 'nas_search', 'nas_address', 'folder_link')):\n        _efsp_load(screen, 'card_icon%d' % index, icon)\n    _efsp_storage_icons(screen)\n    return result\n\n\ndef _efsp_focus(screen):\n    result = _EFSP_FOCUS(screen)\n    if 'source_card_fill' in screen:\n        widget = screen['source_card_fill']\n        if screen.focus_zone == 'cards':\n            x, y = _EMBYFLOW_V18_ADD_CARD_POSITIONS[screen.card_index]\n            widget.instance.move(EFP(x + 3, y + 3))\n            widget.instance.resize(EFS(252, 244))\n            widget.show()\n        else:\n            widget.hide()\n    return result\n\n\nEmbyFlowLocalAddSourceScreenV18.__init__ = _efsp_init\nEmbyFlowLocalAddSourceScreenV18.layout_ready = _efsp_layout\nEmbyFlowLocalAddSourceScreenV18.refresh_locations = _efsp_locations\nEmbyFlowLocalAddSourceScreenV18.apply_focus = _efsp_focus\n# EMBYFLOW_SOURCE_SETUP_PICONS_V1_20261031_END\n"
ASSETS = {'disk.png': '', 'disk_usb.png': '', 'folder_link.png': '', 'nas_address.png': '', 'nas_search.png': '', 'network.png': '', 'usb.png': ''}
MARKER = '# EMBYFLOW_SOURCE_SETUP_PICONS_V1_20261031_BEGIN'


def transform(source):
    if MARKER in source:
        raise ValueError('Quellen-Picons V1 sind bereits installiert; nichts geaendert.')
    tree = ast.parse(source)
    classes = [n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == 'EmbyFlowLocalAddSourceScreenV18']
    if len(classes) != 1:
        raise ValueError('Erwartete Ansicht zum Hinzufuegen einer Quelle fehlt.')
    cls = classes[0]
    nodes = [n for n in cls.body if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'skin' for t in n.targets)]
    if len(nodes) != 1 or not isinstance(nodes[0].value, ast.Call):
        raise ValueError('Skin nicht eindeutig; Abbruch.')
    node = nodes[0]
    skin = ast.literal_eval(node.value.args[0])
    xml = ET.fromstring(skin)
    names = {e.get('name') for e in xml if e.tag == 'widget'}
    if not {'card_icon%d' % i for i in range(4)}.union({'storage_icon%d' % i for i in range(4)}).issubset(names):
        raise ValueError('Erwartete Bildfelder fehlen; Abbruch.')
    for method in ('__init__', 'layout_ready', 'refresh_locations', 'apply_focus'):
        if not any(isinstance(n, ast.FunctionDef) and n.name == method for n in cls.body):
            raise ValueError('Erwartete Methode fehlt: ' + method)
    def edit_tag(match):
        tag = match.group(0)
        if tag.startswith('<eLabel') and 'text=' in tag and 'zPosition=' not in tag:
            tag = tag[:-2] + ' zPosition="5" />'
        for i, x in enumerate((222, 500, 778, 1056)):
            if tag.startswith('<eLabel') and 'position="%d,286" size="258,250"' % x in tag:
                tag = tag.replace('backgroundColor="#0C1827"', 'backgroundColor="#102338"')
            if 'name="card_icon%d"' % i in tag:
                tag = re.sub(r'position="[^"]+"', 'position="%d,298"' % (x + 73), tag)
                tag = tag.replace('size="88,88"', 'size="112,112"').replace('zPosition="5"', 'zPosition="10"')
        return tag
    skin = re.sub(r'<(?:eLabel|widget)\b[^>]*?/>', edit_tag, skin)
    additions = ['<widget name="source_card_fill" position="225,289" size="252,244" backgroundColor="#153858" zPosition="1" />']
    for x in (222, 500, 778, 1056):
        additions.append('<eLabel position="%d,294" size="218,116" backgroundColor="#102337" cornerRadius="12" widgetBorderWidth="1" widgetBorderColor="#263D59" zPosition="2" />' % (x + 20))
    skin = skin.replace('</screen>', '\n'.join(additions) + '\n</screen>')
    ET.fromstring(skin)
    lines = source.splitlines(keepends=True)
    changed = '    skin = scale_skin(' + repr(skin) + ')\n'
    result = ''.join(lines[:node.lineno-1]) + changed + ''.join(lines[node.end_lineno:])
    result = result.rstrip() + '\n\n' + RUNTIME.rstrip() + '\n'
    compile(result, '<EmbyFlowE2-source-picons>', 'exec')
    return result


def atomic_write(path, data, mode=0o644, owner=None):
    fd, tmp = tempfile.mkstemp(prefix='.source_picons_', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'wb') as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        if owner and hasattr(os, 'chown'):
            os.chown(tmp, *owner)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--apply', action='store_true')
    parser.add_argument('--path', default='/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/plugin.py')
    args = parser.parse_args()
    path = Path(args.path)
    original = path.read_bytes()
    updated = transform(original.decode('utf-8')).encode('utf-8')
    decoded = {}
    for name, encoded in ASSETS.items():
        data = base64.b64decode(encoded, validate=True)
        if not data.startswith(b'\x89PNG\r\n\x1a\n') or data[16:24] != b'\x00\x00\x00\x80\x00\x00\x00\x80':
            raise ValueError('Ungueltiges Picon: ' + name)
        decoded[name] = data
    print('Quellenansicht, vollstaendige Python-Syntax und 7 PNG-Picons: OK')
    if not args.apply:
        print('Nur geprueft; nichts geaendert.')
        return
    assetdir = path.parent / 'assets' / 'source_setup_v1'
    if assetdir.exists():
        raise ValueError('Picon-Zielordner existiert bereits; Abbruch ohne Aenderung.')
    if path.read_bytes() != original:
        raise RuntimeError('Plugin wurde zwischenzeitlich geaendert.')
    backup = path.with_name(path.name + '.before_source_picons_' + datetime.now().strftime('%Y%m%d_%H%M%S_%f') + '.bak')
    shutil.copy2(path, backup)
    if backup.read_bytes() != original:
        raise RuntimeError('Sicherungspruefung fehlgeschlagen.')
    details = path.stat()
    assetdir.mkdir(parents=True)
    committed = False
    try:
        for name, data in decoded.items():
            atomic_write(assetdir / name, data)
            if (assetdir / name).read_bytes() != data:
                raise RuntimeError('Picon-Pruefung fehlgeschlagen: ' + name)
        if path.read_bytes() != original:
            raise RuntimeError('Plugin wurde zwischenzeitlich geaendert.')
        atomic_write(path, updated, stat.S_IMODE(details.st_mode), (details.st_uid, details.st_gid))
        committed = True
    finally:
        if not committed:
            for name in decoded:
                candidate = assetdir / name
                if candidate.exists():
                    candidate.unlink()
            assetdir.rmdir()
    print('Sicherung: ' + str(backup))
    print('OK: Picons und Kachelgestaltung installiert. SHA256: ' + hashlib.sha256(updated).hexdigest())


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print('ABBRUCH: ' + str(error), file=sys.stderr)
        sys.exit(1)
